package com.bank.loan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.logging.*;

public class LoanScheduleDemo {
    private static final Logger log = Logger.getLogger("LoanSchedule");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        LoanScheduleService service = new LoanScheduleService();

        List<LocalDate> dates = service.dueDates(LocalDate.of(2026, 1, 15), 12);
        log.info(() -> "First due date: " + dates.get(0) + ", last: " + dates.get(dates.size() - 1));
        log.info(() -> "Total due dates: " + dates.size());

        List<BigDecimal> balances = service.balanceSchedule(
            new BigDecimal("120000"), new BigDecimal("10000"), 12);
        log.info(() -> "Opening balance: " + balances.get(0));
        log.info(() -> "Closing balance: " + balances.get(balances.size() - 1));
    }
}

// ─── Would be in service/LoanScheduleService.java ───
class LoanScheduleService {
    // twelve monthly due dates from an endless iterate stream, bounded by limit
    List<LocalDate> dueDates(LocalDate start, int months) {
        return java.util.stream.Stream
            .iterate(start, d -> d.plusMonths(1))   // seed, then +1 month forever
            .limit(months)                           // bound the infinite stream
            .collect(java.util.stream.Collectors.toList());
    }

    // running balance after each installment (BigDecimal for money)
    List<BigDecimal> balanceSchedule(BigDecimal opening, BigDecimal monthlyPrincipal, int months) {
        return java.util.stream.Stream
            .iterate(opening, b -> b.subtract(monthlyPrincipal))
            .limit(months)
            .collect(java.util.stream.Collectors.toList());
    }
}
